/**
 * Creates an icon, or a cursor, from an ICONINFO structure.
 *
 * The bitmaps are copied: you still own and must delete the originals.
 * Free the result with DestroyIcon. With the icon component, only icons
 * are supported: set fIcon to TRUE. With iconcurs, monochrome cursors
 * can be created too. Windows CE has no colour cursors.
 *
 * @param piconinfo The icon's mask and colour bitmaps and hotspot.
 * @return The icon, or NULL on failure (see GetLastError).
 */
